/**
 * vinext-supported public modules whose declarations cannot be vendored
 * directly from the installed Next.js package, plus vinext-specific extensions.
 * The primary shared surface is generated by scripts/sync-next-types.mjs instead.
 */
// oxlint-disable-next-line typescript/triple-slash-reference
/// <reference path="./next-shims-missing-modules-vinext.d.ts" />

// Next.js publishes this entrypoint with an unresolved type-only import from
// its private, compiled copy of web-vitals. Keep the public function signature
// here so consuming projects do not need either next or web-vitals installed.
declare module "next/web-vitals" {
  export function useReportWebVitals(
    reportWebVitalsFn: (metric: {
      name: "CLS" | "FCP" | "FID" | "INP" | "LCP" | "TTFB";
      value: number;
      rating: "good" | "needs-improvement" | "poor";
      delta: number;
      id: string;
      entries: PerformanceEntry[];
      navigationType:
        | "navigate"
        | "reload"
        | "back-forward"
        | "back-forward-cache"
        | "prerender"
        | "restore";
    }) => void,
  ): void;
}

declare module "next/navigation" {
  export function useRouter(): import("@vinext/types/next/upstream/dist/shared/lib/app-router-context.shared-runtime").AppRouterInstance & {
    bfcacheId: string;
  };
}

// Cache Components parameter matching, newer than the vendored Next.js
// declarations: https://github.com/vercel/next.js/blob/canary/packages/next/src/types.ts
declare module "next" {
  /**
   * Optional contextual typing for parameter matching exports. Use
   * `satisfies ParamMatching` to check modes without widening the object's keys,
   * or provide parameter names for an explicit type annotation.
   */
  export type ParamMatching<ParamName extends string = string> = Partial<
    Record<ParamName, "not-found" | "blocking" | "fallback" | "dynamic">
  >;
}

// Cache Components render stage boundaries, newer than the vendored Next.js
// declarations: https://github.com/vercel/next.js/blob/canary/packages/next/cache.d.ts
declare module "next/cache" {
  export function prefetch(): Promise<void>;
  export function navigation(): Promise<void>;
}
